files.bin/init.ts:
import { readFileSync } from "node:fs";
import { arg } from "./args";
export const init = () => readFileSync(arg(0), "utf8").length;

files.bin/lint.ts:
import { readFileSync } from "node:fs";
import { arg } from "./args";
export const lint = () => readFileSync(arg(0), "utf8").includes("\t");

files.bin/count.ts:
import { readFileSync } from "node:fs";
import { arg } from "./args";
export const count = () => readFileSync(arg(0), "utf8").split("\n").length;
